/*
 * Base 229942f schema snapshot (journal-complete at 0081) - committed fixture.
 * Provenance: generated by building a pristine database through the BASE
 * commit production initDb (drizzle journal 0000..0081, staged migration
 * runner included) and dumping sqlite_master DDL. The candidate migration
 * 0082 applies onto THIS schema state in the upgrade tests. Deterministic;
 * no network, no git, no external clone at test time.
 */
CREATE TABLE __drizzle_migrations (id INTEGER PRIMARY KEY AUTOINCREMENT, hash TEXT NOT NULL, created_at NUMERIC);

CREATE TABLE `agent_messages` (
	`id` text PRIMARY KEY NOT NULL,
	`habitat_id` text NOT NULL,
	`from_agent_id` text NOT NULL,
	`to_agent_id` text NOT NULL,
	`task_id` text,
	`subject` text NOT NULL,
	`body` text NOT NULL,
	`message_type` text DEFAULT 'info' NOT NULL,
	`priority` text DEFAULT 'normal' NOT NULL,
	`read_at` text,
	`created_at` text DEFAULT '(datetime(''now''))' NOT NULL,
	FOREIGN KEY (`habitat_id`) REFERENCES `habitats`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`from_agent_id`) REFERENCES `agents`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`to_agent_id`) REFERENCES `agents`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`task_id`) REFERENCES `tasks`(`id`) ON UPDATE no action ON DELETE cascade
);

CREATE TABLE `agents` (
	`id` text PRIMARY KEY NOT NULL,
	`name` text NOT NULL,
	`type` text NOT NULL,
	`domain` text NOT NULL,
	`capabilities` text NOT NULL,
	`status` text DEFAULT 'idle' NOT NULL,
	`current_task_id` text,
	`api_key` text NOT NULL,
	`created_at` text DEFAULT '(datetime(''now''))' NOT NULL,
	`last_heartbeat` text DEFAULT '(datetime(''now''))' NOT NULL,
	`metadata` text NOT NULL,
	`rate_limit_per_minute` integer
);

CREATE TABLE `audit_export_schedules` (
	`id` text PRIMARY KEY NOT NULL,
	`habitat_id` text NOT NULL,
	`name` text NOT NULL,
	`format` text NOT NULL,
	`filters` text NOT NULL,
	`schedule` text NOT NULL,
	`destination` text DEFAULT 'local' NOT NULL,
	`destination_config` text NOT NULL,
	`enabled` integer DEFAULT true NOT NULL,
	`last_run_at` text,
	`next_run_at` text NOT NULL,
	`created_by` text NOT NULL,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	FOREIGN KEY (`habitat_id`) REFERENCES `habitats`(`id`) ON UPDATE no action ON DELETE cascade
);

CREATE TABLE "automation_delivery_action_checkpoints" (
  id TEXT PRIMARY KEY,
  delivery_id TEXT NOT NULL REFERENCES automation_rule_deliveries(id) ON DELETE CASCADE,
  action_index INTEGER NOT NULL,
  action_key TEXT NOT NULL,
  action_type TEXT NOT NULL,
  idempotency_key TEXT,
  state TEXT NOT NULL DEFAULT 'pending'
    CHECK (state IN ('pending', 'proved', 'failed')),
  receipt TEXT,
  terminal_disposition TEXT,
  predecessor_checkpoint_id TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  proved_at TEXT,
  UNIQUE (delivery_id, action_index),
  CHECK ((state != 'proved') OR (receipt IS NOT NULL AND proved_at IS NOT NULL))
);

CREATE TABLE automation_delivery_dispositions (
  id TEXT PRIMARY KEY,
  delivery_id TEXT NOT NULL,
  inbox_id TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('waive', 'successor_generation')),
  actor_type TEXT NOT NULL,
  actor_id TEXT NOT NULL,
  reason TEXT NOT NULL,
  outcome TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE automation_event_inbox (
  id TEXT PRIMARY KEY,
  event_type TEXT NOT NULL,
  event_id TEXT NOT NULL,
  habitat_id TEXT NOT NULL,
  payload TEXT NOT NULL,
  state TEXT NOT NULL DEFAULT 'pending' CHECK (state IN ('pending', 'terminal')),
  admitted_at TEXT NOT NULL DEFAULT (datetime('now')),
  terminal_at TEXT,
  UNIQUE (event_type, event_id)
);

CREATE TABLE automation_rule_deliveries (
  id TEXT PRIMARY KEY,
  inbox_id TEXT NOT NULL REFERENCES automation_event_inbox(id) ON DELETE CASCADE,
  rule_revision_id TEXT NOT NULL REFERENCES automation_rule_revisions(id),
  rule_id TEXT NOT NULL,
  habitat_id TEXT NOT NULL,
  event_dedupe_key TEXT NOT NULL,
  generation INTEGER NOT NULL DEFAULT 1,
  predecessor_delivery_id TEXT,
  retry_reason TEXT,
  state TEXT NOT NULL DEFAULT 'pending'
    CHECK (state IN ('pending', 'leased', 'terminal', 'attention_required', 'waived')),
  lease_owner TEXT,
  lease_fence TEXT,
  lease_expires_at TEXT,
  automation_run_id TEXT,
  proof_classification TEXT,
  retry_count INTEGER NOT NULL DEFAULT 0,
  terminal_disposition TEXT,
  terminal_detail TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  terminal_at TEXT,
  UNIQUE (event_dedupe_key, rule_revision_id, generation)
);

CREATE TABLE automation_rule_revisions (
  id TEXT PRIMARY KEY,
  rule_id TEXT NOT NULL,
  habitat_id TEXT NOT NULL,
  revision_number INTEGER NOT NULL,
  name TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  enabled INTEGER NOT NULL,
  priority INTEGER NOT NULL DEFAULT 0,
  trigger TEXT NOT NULL,
  condition TEXT NOT NULL,
  actions TEXT NOT NULL,
  cooldown_seconds INTEGER NOT NULL DEFAULT 300,
  max_runs_per_hour INTEGER NOT NULL DEFAULT 30,
  digest TEXT NOT NULL,
  author_type TEXT NOT NULL,
  author_id TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (rule_id, revision_number)
);

CREATE TABLE `automation_rule_runs` (
	`id` text PRIMARY KEY NOT NULL,
	`rule_id` text NOT NULL,
	`habitat_id` text NOT NULL,
	`trigger_type` text NOT NULL,
	`trigger_event_id` text,
	`target_type` text,
	`target_id` text,
	`fingerprint` text NOT NULL,
	`status` text NOT NULL,
	`skip_reason` text,
	`condition_result` text,
	`action_results` text,
	`metadata` text,
	`started_at` text NOT NULL,
	`finished_at` text, event_dedupe_key TEXT,
	FOREIGN KEY (`rule_id`) REFERENCES `automation_rules`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`habitat_id`) REFERENCES `habitats`(`id`) ON UPDATE no action ON DELETE cascade
);

CREATE TABLE `automation_rules` (
	`id` text PRIMARY KEY NOT NULL,
	`habitat_id` text NOT NULL,
	`name` text NOT NULL,
	`description` text DEFAULT '' NOT NULL,
	`enabled` integer DEFAULT false NOT NULL,
	`priority` integer DEFAULT 0 NOT NULL,
	`trigger` text NOT NULL,
	`condition` text NOT NULL,
	`actions` text NOT NULL,
	`cooldown_seconds` integer DEFAULT 300 NOT NULL,
	`max_runs_per_hour` integer DEFAULT 30 NOT NULL,
	`created_by` text NOT NULL,
	`created_at` text DEFAULT '(datetime(''now''))' NOT NULL,
	`updated_at` text DEFAULT '(datetime(''now''))' NOT NULL,
	`last_run_at` text,
	FOREIGN KEY (`habitat_id`) REFERENCES `habitats`(`id`) ON UPDATE no action ON DELETE cascade
);

CREATE TABLE automation_run_completion_outbox (
  id TEXT PRIMARY KEY,
  run_id TEXT NOT NULL REFERENCES automation_rule_runs(id) ON DELETE CASCADE,
  rule_id TEXT NOT NULL,
  habitat_id TEXT NOT NULL,
  outcome TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  delivered_at TEXT,
  delivery_attempts INTEGER NOT NULL DEFAULT 0,
  last_error TEXT,
  UNIQUE (run_id)
);

CREATE TABLE `chat_integrations` (
	`id` text PRIMARY KEY NOT NULL,
	`habitat_id` text NOT NULL,
	`provider` text NOT NULL,
	`webhook_url` text NOT NULL,
	`channel_id` text,
	`bot_token` text,
	`enabled` integer DEFAULT 1 NOT NULL,
	`events` text NOT NULL,
	`created_at` text DEFAULT '(datetime(''now''))' NOT NULL,
	`updated_at` text DEFAULT '(datetime(''now''))' NOT NULL, `provider_workspace_id` text,
	FOREIGN KEY (`habitat_id`) REFERENCES `habitats`(`id`) ON UPDATE no action ON DELETE cascade
);

CREATE TABLE `chat_speaker_mappings` (
	`id` text PRIMARY KEY NOT NULL,
	`habitat_id` text NOT NULL,
	`integration_id` text NOT NULL,
	`provider` text NOT NULL,
	`provider_workspace_id` text NOT NULL,
	`provider_speaker_id` text NOT NULL,
	`local_user_id` text NOT NULL,
	`created_by` text NOT NULL,
	`created_at` text NOT NULL DEFAULT (datetime('now')),
	FOREIGN KEY (`habitat_id`) REFERENCES `habitats`(`id`) ON DELETE CASCADE,
	FOREIGN KEY (`integration_id`) REFERENCES `chat_integrations`(`id`) ON DELETE CASCADE,
	FOREIGN KEY (`local_user_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT
);

CREATE TABLE `code_branches` (
	`id` text PRIMARY KEY NOT NULL,
	`repository_id` text,
	`provider` text NOT NULL,
	`repo_slug` text,
	`name` text NOT NULL,
	`base_branch` text,
	`head_sha` text,
	`url` text,
	`created_from_task_id` text,
	`verification_state` text DEFAULT 'unverified' NOT NULL,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	`updated_at` text DEFAULT (datetime('now')) NOT NULL,
	FOREIGN KEY (`repository_id`) REFERENCES `habitat_code_repositories`(`id`) ON UPDATE no action ON DELETE set null,
	FOREIGN KEY (`created_from_task_id`) REFERENCES `tasks`(`id`) ON UPDATE no action ON DELETE set null
);

CREATE TABLE `code_changed_files` (
	`id` text PRIMARY KEY NOT NULL,
	`repository_id` text,
	`commit_id` text,
	`pull_request_id` text,
	`provider` text NOT NULL,
	`repo_slug` text,
	`path` text NOT NULL,
	`previous_path` text,
	`change_type` text NOT NULL,
	`additions` integer,
	`deletions` integer,
	`source` text NOT NULL,
	`captured_at` text DEFAULT (datetime('now')) NOT NULL,
	`metadata` text DEFAULT '{}' NOT NULL,
	FOREIGN KEY (`repository_id`) REFERENCES `habitat_code_repositories`(`id`) ON UPDATE no action ON DELETE set null,
	FOREIGN KEY (`commit_id`) REFERENCES `code_commits`(`id`) ON UPDATE no action ON DELETE set null,
	FOREIGN KEY (`pull_request_id`) REFERENCES `pull_requests`(`id`) ON UPDATE no action ON DELETE set null
);

CREATE TABLE `code_commits` (
	`id` text PRIMARY KEY NOT NULL,
	`repository_id` text,
	`provider` text NOT NULL,
	`repo_slug` text,
	`sha` text NOT NULL,
	`branch_id` text,
	`message` text,
	`author_name` text,
	`author_email` text,
	`authored_at` text,
	`url` text,
	`verification_state` text DEFAULT 'unverified' NOT NULL,
	`metadata` text DEFAULT '{}' NOT NULL,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	`updated_at` text DEFAULT (datetime('now')) NOT NULL,
	FOREIGN KEY (`repository_id`) REFERENCES `habitat_code_repositories`(`id`) ON UPDATE no action ON DELETE set null,
	FOREIGN KEY (`branch_id`) REFERENCES `code_branches`(`id`) ON UPDATE no action ON DELETE set null
);

CREATE TABLE `code_evidence_completeness` (
	`target_type` text NOT NULL,
	`target_id` text NOT NULL,
	`status` text NOT NULL,
	`reason_code` text,
	`reason_note` text,
	`marked_by_type` text NOT NULL,
	`marked_by_id` text NOT NULL,
	`updated_at` text DEFAULT (datetime('now')) NOT NULL,
	`created_at` text DEFAULT (datetime('now')) NOT NULL
);

CREATE TABLE `code_evidence_gaps` (
	`id` text PRIMARY KEY NOT NULL,
	`target_type` text NOT NULL,
	`target_id` text NOT NULL,
	`reason_code` text NOT NULL,
	`reason_note` text,
	`status` text DEFAULT 'active' NOT NULL,
	`reported_by_type` text NOT NULL,
	`reported_by_id` text NOT NULL,
	`reported_at` text DEFAULT (datetime('now')) NOT NULL,
	`resolved_by_type` text,
	`resolved_by_id` text,
	`resolved_at` text,
	`resolution_reason` text,
	`metadata` text DEFAULT '{}' NOT NULL
);

CREATE TABLE `code_evidence_links` (
	`id` text PRIMARY KEY NOT NULL,
	`target_type` text NOT NULL,
	`target_id` text NOT NULL,
	`evidence_type` text NOT NULL,
	`evidence_id` text,
	`external_url` text,
	`normalized_external_url` text,
	`title` text,
	`description` text,
	`link_source` text NOT NULL,
	`link_sources` text DEFAULT '[]' NOT NULL,
	`linked_by_type` text NOT NULL,
	`linked_by_id` text NOT NULL,
	`linked_at` text DEFAULT (datetime('now')) NOT NULL,
	`verification_state` text DEFAULT 'unverified' NOT NULL,
	`confidence` real,
	`status` text DEFAULT 'active' NOT NULL,
	`corrected_by_type` text,
	`corrected_by_id` text,
	`corrected_at` text,
	`correction_reason` text,
	`replacement_link_id` text,
	`allow_external_repository` integer DEFAULT false NOT NULL,
	`metadata` text DEFAULT '{}' NOT NULL,
	FOREIGN KEY (`replacement_link_id`) REFERENCES `code_evidence_links`(`id`) ON UPDATE no action ON DELETE set null
);

CREATE TABLE `code_reviews` (
	`id` text PRIMARY KEY NOT NULL,
	`pull_request_id` text,
	`repository_id` text,
	`provider` text NOT NULL,
	`repo_slug` text,
	`review_url` text,
	`review_status` text DEFAULT 'pending' NOT NULL,
	`reviewer_name` text,
	`reviewer_id` text,
	`submitted_at` text,
	`verification_state` text DEFAULT 'unverified' NOT NULL,
	`metadata` text DEFAULT '{}' NOT NULL,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	`updated_at` text DEFAULT (datetime('now')) NOT NULL,
	FOREIGN KEY (`pull_request_id`) REFERENCES `pull_requests`(`id`) ON UPDATE no action ON DELETE set null,
	FOREIGN KEY (`repository_id`) REFERENCES `habitat_code_repositories`(`id`) ON UPDATE no action ON DELETE set null
);

CREATE TABLE `columns` (
	`id` text PRIMARY KEY NOT NULL,
	`habitat_id` text NOT NULL,
	`name` text NOT NULL,
	`order` integer NOT NULL,
	`wip_limit` integer,
	`auto_advance` integer DEFAULT false NOT NULL,
	`requires_claim` integer DEFAULT true NOT NULL,
	`next_column_id` text,
	`is_terminal` integer DEFAULT false NOT NULL,
	FOREIGN KEY (`habitat_id`) REFERENCES `habitats`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`next_column_id`) REFERENCES `columns`(`id`) ON UPDATE no action ON DELETE no action
);

CREATE TABLE `cumulative_flow_snapshots` (
	`id` text PRIMARY KEY NOT NULL,
	`habitat_id` text NOT NULL,
	`snapshot_date` text NOT NULL,
	`counts_by_column` text NOT NULL,
	`counts_by_status` text NOT NULL,
	`source` text DEFAULT 'generated' NOT NULL,
	`completeness` text DEFAULT 'complete' NOT NULL,
	`warnings` text NOT NULL,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	FOREIGN KEY (`habitat_id`) REFERENCES `habitats`(`id`) ON UPDATE no action ON DELETE cascade
);

CREATE TABLE `daemon_agents` (
	`id` text PRIMARY KEY NOT NULL,
	`daemon_id` text NOT NULL,
	`agent_id` text NOT NULL,
	`cli_type` text NOT NULL,
	`cli_version` text,
	`cli_path` text NOT NULL,
	`status` text DEFAULT 'idle' NOT NULL,
	`last_seen_at` text,
	`created_at` text DEFAULT '(datetime(''now''))' NOT NULL,
	`updated_at` text DEFAULT '(datetime(''now''))' NOT NULL,
	FOREIGN KEY (`daemon_id`) REFERENCES `daemon_instances`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`agent_id`) REFERENCES `agents`(`id`) ON UPDATE no action ON DELETE cascade
);

CREATE TABLE `daemon_instances` (
	`id` text PRIMARY KEY NOT NULL,
	`name` text NOT NULL,
	`hostname` text NOT NULL,
	`token_hash` text NOT NULL,
	`max_concurrent` integer DEFAULT 4 NOT NULL,
	`daemon_version` text NOT NULL,
	`last_heartbeat_at` text,
	`status` text DEFAULT 'online' NOT NULL,
	`metadata` text NOT NULL,
	`created_at` text DEFAULT '(datetime(''now''))' NOT NULL,
	`updated_at` text DEFAULT '(datetime(''now''))' NOT NULL
);

CREATE TABLE `daemon_sessions` (
	`id` text PRIMARY KEY NOT NULL,
	`daemon_id` text NOT NULL,
	`agent_id` text NOT NULL,
	`task_id` text NOT NULL,
	`habitat_id` text NOT NULL,
	`pid` integer,
	`cli_session_id` text,
	`workdir` text NOT NULL,
	`status` text DEFAULT 'starting' NOT NULL,
	`last_progress` text,
	`started_at` text NOT NULL,
	`ended_at` text,
	`updated_at` text DEFAULT '(datetime(''now''))' NOT NULL, `execution_token` TEXT,
	FOREIGN KEY (`daemon_id`) REFERENCES `daemon_instances`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`agent_id`) REFERENCES `agents`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`task_id`) REFERENCES `tasks`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`habitat_id`) REFERENCES `habitats`(`id`) ON UPDATE no action ON DELETE cascade
);

CREATE TABLE `effect_receipt_admin_actions` (
	`id` text PRIMARY KEY NOT NULL,
	`receipt_id` text NOT NULL,
	`target_id` text,
	`action` text NOT NULL,
	`actor_type` text NOT NULL,
	`actor_id` text NOT NULL,
	`occurred_at` text NOT NULL,
	FOREIGN KEY (`receipt_id`) REFERENCES `effect_receipts`(`id`) ON UPDATE no action ON DELETE cascade
);

CREATE TABLE `effect_receipt_attempts` (
	`id` text PRIMARY KEY NOT NULL,
	`receipt_id` text NOT NULL,
	`target_id` text,
	`attempt` integer NOT NULL,
	`code` text NOT NULL,
	`actor` text NOT NULL DEFAULT 'deliverer',
	`occurred_at` text NOT NULL,
	FOREIGN KEY (`receipt_id`) REFERENCES `effect_receipts`(`id`) ON UPDATE no action ON DELETE cascade
);

CREATE TABLE `effect_receipt_targets` (
	`id` text PRIMARY KEY NOT NULL,
	`receipt_id` text NOT NULL,
	`habitat_id` text NOT NULL,
	`target_key` text NOT NULL,
	`plugin_id` text NOT NULL,
	`contribution_id` text NOT NULL,
	`state` text NOT NULL DEFAULT 'pending',
	`attempts` integer NOT NULL DEFAULT 0,
	`last_error_code` text,
	`lease_owner` text,
	`lease_token` text,
	`lease_expires_at` text,
	`created_at` text NOT NULL,
	`delivered_at` text,
	FOREIGN KEY (`receipt_id`) REFERENCES `effect_receipts`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`habitat_id`) REFERENCES `habitats`(`id`) ON UPDATE no action ON DELETE cascade
);

CREATE TABLE `effect_receipts` (
	`id` text PRIMARY KEY NOT NULL,
	`subject_type` text NOT NULL,
	`subject_id` text NOT NULL,
	`habitat_id` text NOT NULL,
	`task_id` text,
	`consumer` text NOT NULL,
	`state` text NOT NULL DEFAULT 'pending',
	`attempts` integer NOT NULL DEFAULT 0,
	`last_error_code` text,
	`lease_owner` text,
	`lease_token` text,
	`lease_expires_at` text,
	`causal_snapshot` text,
	`created_at` text NOT NULL,
	`delivered_at` text,
	FOREIGN KEY (`habitat_id`) REFERENCES `habitats`(`id`) ON UPDATE no action ON DELETE cascade
);

CREATE TABLE `effort_entries` (
	`id` text PRIMARY KEY NOT NULL,
	`task_id` text NOT NULL,
	`actor_type` text NOT NULL,
	`actor_id` text,
	`minutes` integer NOT NULL,
	`source` text NOT NULL,
	`note` text,
	`started_at` text,
	`ended_at` text,
	`recorded_at` text DEFAULT (datetime('now')) NOT NULL,
	`corrects_entry_id` text,
	`correction_reason` text,
	`metadata` text,
	FOREIGN KEY (`task_id`) REFERENCES `tasks`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`corrects_entry_id`) REFERENCES `effort_entries`(`id`) ON UPDATE no action ON DELETE set null
);

CREATE TABLE `external_identities` (
	`id` text PRIMARY KEY NOT NULL,
	`provider_id` text NOT NULL,
	`habitat_id` text NOT NULL,
	`external_subject` text NOT NULL,
	`account_login` text,
	`account_name` text,
	`email` text,
	`profile_data` text DEFAULT '{}' NOT NULL,
	`local_user_id` text,
	`remote_participant_id` text,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	`updated_at` text DEFAULT (datetime('now')) NOT NULL,
	FOREIGN KEY (`provider_id`) REFERENCES `identity_providers`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`habitat_id`) REFERENCES `habitats`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`local_user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE set null
);

CREATE TABLE `external_intake_candidates` (
	`id` text PRIMARY KEY NOT NULL,
	`connection_id` text NOT NULL,
	`habitat_id` text NOT NULL,
	`provider` text NOT NULL,
	`external_id` text NOT NULL,
	`external_key` text NOT NULL,
	`external_url` text NOT NULL,
	`source_kind` text,
	`source_status` text,
	`source_priority` text,
	`source_assignees` text NOT NULL,
	`source_reporter` text,
	`source_labels` text NOT NULL,
	`source_title` text NOT NULL,
	`source_body` text,
	`normalized_summary` text,
	`recommended_mission_title` text,
	`recommended_mission_description` text,
	`review_status` text DEFAULT 'new' NOT NULL,
	`promoted_mission_id` text,
	`raw_provider_payload` text,
	`external_updated_at` text,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	`updated_at` text DEFAULT (datetime('now')) NOT NULL,
	FOREIGN KEY (`connection_id`) REFERENCES `integration_connections`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`habitat_id`) REFERENCES `habitats`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`promoted_mission_id`) REFERENCES `missions`(`id`) ON UPDATE no action ON DELETE set null
);

CREATE TABLE `external_issue_links` (
	`id` text PRIMARY KEY NOT NULL,
	`connection_id` text NOT NULL,
	`habitat_id` text NOT NULL,
	`mission_id` text NOT NULL,
	`provider` text NOT NULL,
	`external_id` text NOT NULL,
	`external_key` text NOT NULL,
	`external_url` text NOT NULL,
	`external_status` text NOT NULL,
	`external_updated_at` text,
	`provider_labels` text NOT NULL,
	`last_synced_at` text,
	`sync_status` text DEFAULT 'synced' NOT NULL,
	`sync_warning` text,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	`updated_at` text DEFAULT (datetime('now')) NOT NULL,
	FOREIGN KEY (`connection_id`) REFERENCES `integration_connections`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`habitat_id`) REFERENCES `habitats`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`mission_id`) REFERENCES `missions`(`id`) ON UPDATE no action ON DELETE cascade
);

CREATE TABLE extracted_finding_promotions (
  id TEXT PRIMARY KEY NOT NULL,
  finding_id TEXT NOT NULL REFERENCES extracted_findings(id) ON DELETE CASCADE,
  destination_type TEXT NOT NULL,
  destination_key TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending',
  idempotency_key TEXT NOT NULL,
  lease_owner TEXT NOT NULL,
  lease_generation INTEGER NOT NULL,
  target_type TEXT,
  target_id TEXT,
  target_version TEXT,
  consumed_finding_revision INTEGER NOT NULL,
  error TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  completed_at TEXT
);

CREATE TABLE extracted_finding_reviews (
  id TEXT PRIMARY KEY NOT NULL,
  finding_id TEXT NOT NULL REFERENCES extracted_findings(id) ON DELETE CASCADE,
  decision TEXT NOT NULL,
  reason TEXT,
  reviewer_type TEXT NOT NULL,
  reviewer_id TEXT NOT NULL,
  expected_decision_version INTEGER NOT NULL,
  resulting_decision_version INTEGER NOT NULL,
  resolved_citation_states TEXT NOT NULL DEFAULT '[]',
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE extracted_finding_scope_refs (
  id TEXT PRIMARY KEY NOT NULL,
  finding_id TEXT NOT NULL REFERENCES extracted_findings(id) ON DELETE CASCADE,
  scope_type TEXT NOT NULL,
  scope_id TEXT NOT NULL,
  derived_from_source_id TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE extracted_finding_sources (
  id TEXT PRIMARY KEY NOT NULL,
  finding_id TEXT NOT NULL REFERENCES extracted_findings(id) ON DELETE CASCADE,
  source_type TEXT NOT NULL,
  source_id TEXT NOT NULL,
  source_version TEXT NOT NULL DEFAULT '',
  role TEXT NOT NULL,
