	`repository_id` text,
	`commit_id` text,
	`branch_evidence_id` text,
	`verification_state` text,
	`metadata` text,
	`created_at` text DEFAULT '(datetime(''now''))',
	`updated_at` text DEFAULT '(datetime(''now''))',
