	`order_index` integer NOT NULL,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	FOREIGN KEY (`template_id`) REFERENCES `quality_checklist_templates`(`id`) ON UPDATE no action ON DELETE cascade
);

CREATE TABLE `quality_checklist_templates` (
	`id` text PRIMARY KEY NOT NULL,
	`name` text NOT NULL,
	`description` text DEFAULT '' NOT NULL,
	`category` text NOT NULL,
	`is_required` integer DEFAULT true NOT NULL,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	`updated_at` text DEFAULT (datetime('now')) NOT NULL
);

CREATE TABLE "release_activation_epoch_groups" (
  id TEXT PRIMARY KEY,
  epoch_id TEXT NOT NULL,
  release_id TEXT NOT NULL REFERENCES releases(id) ON DELETE CASCADE,
  habitat_id TEXT NOT NULL,
  mission_id TEXT NOT NULL,
  mission_created_at TEXT NOT NULL,
  position INTEGER NOT NULL,
  finding_ids TEXT NOT NULL,
  gate_type TEXT,
  gate_version TEXT,
  membership_digest TEXT NOT NULL,
  disposition TEXT NOT NULL DEFAULT 'pending'
    CHECK (disposition IN ('pending', 'activated', 'deferred_changed', 'deferred_oversized', 'deferred_budget')),
  disposition_at TEXT,
  disposition_detail TEXT,
  activated_finding_count INTEGER,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY (epoch_id, release_id)
    REFERENCES release_activation_epochs(id, release_id) ON DELETE CASCADE
);

CREATE TABLE release_activation_epoch_groups_orphans_0074(
  id TEXT,
  epoch_id TEXT,
  release_id TEXT,
  habitat_id TEXT,
  mission_id TEXT,
  mission_created_at TEXT,
  position INT,
  finding_ids TEXT,
  gate_type TEXT,
  gate_version TEXT,
  membership_digest TEXT,
  disposition TEXT,
  disposition_at TEXT,
  disposition_detail TEXT,
  activated_finding_count INT,
  created_at TEXT
);

CREATE TABLE release_activation_epochs (
  id TEXT PRIMARY KEY,
  release_id TEXT NOT NULL UNIQUE REFERENCES releases(id) ON DELETE CASCADE,
  habitat_id TEXT NOT NULL REFERENCES habitats(id) ON DELETE CASCADE,
  frozen_cap INTEGER,
  auto_promote_enabled INTEGER NOT NULL DEFAULT 1,
  eligibility_digest TEXT NOT NULL,
  completed_at TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE release_projection_deliveries (
  id TEXT PRIMARY KEY,
  release_id TEXT NOT NULL REFERENCES releases(id) ON DELETE CASCADE,
  habitat_id TEXT NOT NULL REFERENCES habitats(id) ON DELETE CASCADE,
  projection_kind TEXT NOT NULL CHECK (projection_kind IN (
    'activation_reconciliation',
    'deadline_notification',
    'activation_notification',
    'retrospective_pulse',
    'release_shipped'
  )),
  state TEXT NOT NULL CHECK (state IN ('pending', 'completed')),
  idempotency_key TEXT NOT NULL,
  attempt_count INTEGER NOT NULL DEFAULT 0,
  last_error TEXT,
  output_identity TEXT,
  completed_at TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (release_id, projection_kind)
);

CREATE TABLE releases (
  id TEXT PRIMARY KEY NOT NULL,
  habitat_id TEXT NOT NULL REFERENCES habitats(id) ON DELETE CASCADE,
  version TEXT NOT NULL,
  release_type TEXT NOT NULL,
  detected_by TEXT NOT NULL,
  release_notes TEXT,
  detected_at TEXT NOT NULL DEFAULT (datetime('now')),
  metadata TEXT NOT NULL DEFAULT '{}'
);

CREATE TABLE `remote_credentials` (
	`id` text PRIMARY KEY NOT NULL,
	`remote_participant_id` text NOT NULL,
	`habitat_id` text NOT NULL,
