	FOREIGN KEY (`habitat_id`) REFERENCES `habitats`(`id`) ON UPDATE no action ON DELETE cascade
);

CREATE TABLE `remote_webhook_endpoints` (
	`id` text PRIMARY KEY NOT NULL,
	`remote_pod_id` text NOT NULL,
	`habitat_id` text NOT NULL,
