	`last_test_at` text,
	`last_test_status` text,
	`approved_by` text,
	`approved_at` text,
	`enabled_by` text,
	`enabled_at` text,
	`rejected_at` text,
	`rejected_by` text,
	`reject_reason` text,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	`updated_at` text DEFAULT (datetime('now')) NOT NULL, `encrypted_secret` text,
	FOREIGN KEY (`remote_pod_id`) REFERENCES `remote_pods`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`habitat_id`) REFERENCES `habitats`(`id`) ON UPDATE no action ON DELETE cascade
);

CREATE TABLE `review_rules` (
