	`author_type` text NOT NULL,
	`author_id` text NOT NULL,
	`content` text NOT NULL,
	`created_at` text DEFAULT '(datetime(''now''))' NOT NULL,
	`updated_at` text DEFAULT '(datetime(''now''))' NOT NULL,
	FOREIGN KEY (`task_id`) REFERENCES `tasks`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`parent_id`) REFERENCES `task_comments`(`id`) ON UPDATE no action ON DELETE cascade
);

CREATE TABLE task_creation_assignment_reservations (
  id TEXT PRIMARY KEY NOT NULL,
  task_id TEXT NOT NULL,
  attempt_id TEXT NOT NULL REFERENCES task_creation_attempts(id) ON DELETE CASCADE,
  requested_agent_id TEXT,
  lease_owner TEXT,
  lease_expires_at TEXT,
  deadline TEXT NOT NULL,
  state TEXT NOT NULL DEFAULT 'active',
  failure_reason TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE task_creation_attempts (
  id TEXT PRIMARY KEY NOT NULL,
  source TEXT NOT NULL,
  source_scope_kind TEXT NOT NULL,
  source_scope_id TEXT NOT NULL,
  attempt_key TEXT NOT NULL,
  request_fingerprint TEXT NOT NULL,
  publication_kind TEXT NOT NULL,
  actor_type TEXT NOT NULL,
  actor_id TEXT NOT NULL,
  causal_context TEXT,
  state TEXT NOT NULL DEFAULT 'pending',
  lease_owner TEXT,
  lease_expires_at TEXT,
  prospective_task_id TEXT,
  committed_task_id TEXT,
  committed_mission_id TEXT,
  envelope_event_id TEXT,
  reservation_id TEXT,
  terminal_outcome TEXT,
  terminal_result TEXT,
  details TEXT,
  reserved_at TEXT NOT NULL DEFAULT (datetime('now')),
  published_at TEXT,
  completed_at TEXT
, habitat_id TEXT);

CREATE TABLE task_creation_dispatch_targets (
  id TEXT PRIMARY KEY NOT NULL,
  event_id TEXT NOT NULL REFERENCES task_creation_envelopes(event_id) ON DELETE CASCADE,
  target_kind TEXT NOT NULL,
  target_key TEXT NOT NULL,
  state TEXT NOT NULL DEFAULT 'pending',
  attempt_count INTEGER NOT NULL DEFAULT 0,
  last_attempt_at TEXT,
  last_error TEXT,
  accepted_at TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE task_creation_envelopes (
  event_id TEXT PRIMARY KEY NOT NULL,
  lifecycle_action TEXT NOT NULL,
  task_id TEXT NOT NULL,
  habitat_id TEXT NOT NULL,
  occurred_at TEXT NOT NULL,
  attempt_id TEXT NOT NULL REFERENCES task_creation_attempts(id) ON DELETE CASCADE,
  actor_type TEXT NOT NULL,
  actor_id TEXT NOT NULL,
  source TEXT NOT NULL,
  causal_context TEXT NOT NULL DEFAULT '{}',
  clone_source_task_id TEXT
);

CREATE TABLE task_creation_governance_decisions (
  id TEXT PRIMARY KEY NOT NULL,
  attempt_id TEXT NOT NULL REFERENCES task_creation_attempts(id) ON DELETE CASCADE,
  prospective_task_id TEXT NOT NULL,
  interceptor_key TEXT NOT NULL,
  governance_fingerprint TEXT NOT NULL,
  decision TEXT NOT NULL,
  plugin_run_id TEXT,
  diagnostics TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE `task_dependencies` (
	`task_id` text NOT NULL,
	`depends_on_id` text NOT NULL,
	PRIMARY KEY(`task_id`, `depends_on_id`),
	FOREIGN KEY (`task_id`) REFERENCES `tasks`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`depends_on_id`) REFERENCES `tasks`(`id`) ON UPDATE no action ON DELETE cascade
);

CREATE TABLE `task_events` (
	`id` text PRIMARY KEY NOT NULL,
	`task_id` text NOT NULL,
	`actor_type` text NOT NULL,
	`actor_id` text NOT NULL,
	`action` text NOT NULL,
	`from_column_id` text,
	`to_column_id` text,
	`from_status` text,
	`to_status` text,
	`metadata` text NOT NULL,
	`timestamp` text DEFAULT '(datetime(''now''))' NOT NULL, `execution_token` text,
	FOREIGN KEY (`task_id`) REFERENCES `tasks`(`id`) ON UPDATE no action ON DELETE cascade
);

CREATE TABLE `task_quality_checklist_items` (
	`id` text PRIMARY KEY NOT NULL,
	`checklist_id` text NOT NULL,
	`item_id` text NOT NULL,
	`is_completed` integer DEFAULT false NOT NULL,
	`completed_by` text,
	`completed_at` text,
	`evidence_url` text,
	`notes` text DEFAULT '' NOT NULL,
	FOREIGN KEY (`checklist_id`) REFERENCES `task_quality_checklists`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`item_id`) REFERENCES `quality_checklist_items`(`id`) ON UPDATE no action ON DELETE cascade
);

CREATE TABLE `task_quality_checklists` (
	`id` text PRIMARY KEY NOT NULL,
	`task_id` text NOT NULL,
	`template_id` text,
	`status` text DEFAULT 'pending' NOT NULL,
	`completed_at` text,
	`completed_by` text,
	`notes` text DEFAULT '' NOT NULL,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	FOREIGN KEY (`task_id`) REFERENCES `tasks`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`template_id`) REFERENCES `quality_checklist_templates`(`id`) ON UPDATE no action ON DELETE set null
);

CREATE TABLE task_recovery_handoffs (
  id TEXT PRIMARY KEY,
  gate_id TEXT NOT NULL REFERENCES task_workflow_gates(id) ON DELETE CASCADE,
  workflow_id TEXT NOT NULL,
  habitat_id TEXT NOT NULL,
  mission_id TEXT NOT NULL,
  downstream_task_id TEXT NOT NULL,
  recovery_depth INTEGER NOT NULL,
  trigger_event_id TEXT NOT NULL,
  frozen_handler_config TEXT NOT NULL,
  handler_fingerprint TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'expected',
  blocked_reason TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  consumed_at TEXT
);

CREATE TABLE `task_reviewers` (
	`id` text PRIMARY KEY NOT NULL,
	`task_id` text NOT NULL,
	`reviewer_type` text NOT NULL,
	`reviewer_id` text NOT NULL,
	`status` text DEFAULT 'pending' NOT NULL,
	`assigned_at` text DEFAULT '(datetime(''now''))' NOT NULL,
	`reviewed_at` text,
	`review_note` text,
	FOREIGN KEY (`task_id`) REFERENCES `tasks`(`id`) ON UPDATE no action ON DELETE cascade
);

CREATE TABLE `task_subtasks` (
	`id` text PRIMARY KEY NOT NULL,
	`task_id` text NOT NULL,
	`title` text NOT NULL,
	`completed` integer DEFAULT false NOT NULL,
	`order` integer DEFAULT 0 NOT NULL,
	`assignee_id` text,
	`created_at` text DEFAULT '(datetime(''now''))' NOT NULL,
	`updated_at` text DEFAULT '(datetime(''now''))' NOT NULL,
	FOREIGN KEY (`task_id`) REFERENCES `tasks`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`assignee_id`) REFERENCES `agents`(`id`) ON UPDATE no action ON DELETE no action
);

CREATE TABLE `task_time_records` (
	`id` text PRIMARY KEY NOT NULL,
	`task_id` text NOT NULL,
	`agent_id` text,
	`minutes_spent` integer NOT NULL,
	`recorded_at` text DEFAULT (datetime('now')) NOT NULL,
	`status_during_work` text NOT NULL,
	FOREIGN KEY (`task_id`) REFERENCES `tasks`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`agent_id`) REFERENCES `agents`(`id`) ON UPDATE no action ON DELETE set null
);

CREATE TABLE `task_watchers` (
	`task_id` text NOT NULL,
	`user_id` text NOT NULL,
	`created_at` text DEFAULT '(datetime(''now''))' NOT NULL,
	PRIMARY KEY(`task_id`, `user_id`),
	FOREIGN KEY (`task_id`) REFERENCES `tasks`(`id`) ON UPDATE no action ON DELETE cascade
);

CREATE TABLE `task_workflow_gates` (
	`id` text PRIMARY KEY NOT NULL,
	`workflow_id` text NOT NULL,
	`mission_id` text NOT NULL,
	`habitat_id` text NOT NULL,
	`upstream_task_id` text NOT NULL,
	`downstream_task_id` text NOT NULL,
	`gate_type` text NOT NULL,
	`match_config` text,
	`condition` text,
	`satisfied` integer DEFAULT false NOT NULL,
	`satisfied_at` text,
	`satisfied_by_event_id` text,
	`recovery_task_id` text,
	`recovery_depth` integer DEFAULT 0 NOT NULL,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	FOREIGN KEY (`workflow_id`) REFERENCES `workflows`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`mission_id`) REFERENCES `missions`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`habitat_id`) REFERENCES `habitats`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`upstream_task_id`) REFERENCES `tasks`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`downstream_task_id`) REFERENCES `tasks`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`recovery_task_id`) REFERENCES `tasks`(`id`) ON UPDATE no action ON DELETE set null
);

CREATE TABLE `tasks` (
	`id` text PRIMARY KEY NOT NULL,
	`mission_id` text NOT NULL,
	`title` text NOT NULL,
	`description` text DEFAULT '' NOT NULL,
	`labels` text NOT NULL,
	`priority` text DEFAULT 'medium' NOT NULL,
	`assigned_agent_id` text,
	`required_domain` text,
	`required_capabilities` text NOT NULL,
	`status` text DEFAULT 'pending' NOT NULL,
	`claimed_at` text,
	`started_at` text,
	`submitted_at` text,
	`completed_at` text,
	`rejected_count` integer DEFAULT 0 NOT NULL,
	`rejection_reason` text,
	`result` text,
	`artifacts` text NOT NULL,
	`created_by` text NOT NULL,
	`created_at` text DEFAULT '(datetime(''now''))' NOT NULL,
	`updated_at` text DEFAULT '(datetime(''now''))' NOT NULL,
	`version` integer DEFAULT 1 NOT NULL,
	`order` integer DEFAULT 0 NOT NULL,
	`delegated_to_agent_id` text,
	`estimated_minutes` integer,
	`retry_policy` text,
	`retry_count` integer DEFAULT 0 NOT NULL,
	`next_retry_at` text,
	`actual_minutes` integer,
	`cycle_time_minutes` integer,
	`lead_time_minutes` integer,
	`estimation_accuracy` real, `remote_assigned_participant_id` text, creation_integrity INTEGER NOT NULL DEFAULT 0, `last_activity_at` text, `execution_token` TEXT, `last_failure_event_id` text, `last_release_event_id` text,
	FOREIGN KEY (`mission_id`) REFERENCES `missions`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`assigned_agent_id`) REFERENCES `agents`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`delegated_to_agent_id`) REFERENCES `agents`(`id`) ON UPDATE no action ON DELETE no action
);

CREATE TABLE `team_members` (
	`id` text PRIMARY KEY NOT NULL,
	`team_id` text NOT NULL,
	`user_id` text NOT NULL,
	`role` text DEFAULT 'member' NOT NULL,
	`joined_at` text DEFAULT '(datetime(''now''))' NOT NULL,
	FOREIGN KEY (`team_id`) REFERENCES `teams`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade
);

CREATE TABLE `teams` (
	`id` text PRIMARY KEY NOT NULL,
	`organization_id` text NOT NULL,
	`name` text NOT NULL,
	`slug` text NOT NULL,
	`created_at` text DEFAULT '(datetime(''now''))' NOT NULL,
	FOREIGN KEY (`organization_id`) REFERENCES `organizations`(`id`) ON UPDATE no action ON DELETE cascade
);

CREATE TABLE triage_cluster_missions (
  id TEXT PRIMARY KEY NOT NULL,
  habitat_id TEXT NOT NULL REFERENCES habitats(id) ON DELETE CASCADE,
  cluster_key TEXT NOT NULL,
  mission_id TEXT NOT NULL REFERENCES missions(id) ON DELETE CASCADE,
  status TEXT NOT NULL DEFAULT 'open',
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  resolved_at TEXT
);

CREATE TABLE triage_publication_occurrences (
  id TEXT PRIMARY KEY,
  habitat_id TEXT NOT NULL REFERENCES habitats(id) ON DELETE CASCADE,
  cluster_key TEXT NOT NULL,
  occurrence_version INTEGER NOT NULL,
  candidate_snapshot TEXT NOT NULL,
  snapshot_digest TEXT NOT NULL UNIQUE,
  rendered_payload TEXT NOT NULL,
  prepared_aggregate TEXT NOT NULL,
  prepared_digest TEXT NOT NULL,
  template_id TEXT NOT NULL,
  template_digest TEXT NOT NULL,
  winner_nonce TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE triage_resolutions (
  id TEXT PRIMARY KEY NOT NULL,
  habitat_id TEXT NOT NULL REFERENCES habitats(id) ON DELETE CASCADE,
  cluster_key TEXT NOT NULL,
  skill_category TEXT NOT NULL,
  source TEXT NOT NULL,
  source_id TEXT NOT NULL,
  root_cause TEXT,
  resolution TEXT,
  resolution_kind TEXT,
  resolved_by_type TEXT,
  resolved_by_id TEXT,
  resolved_at TEXT NOT NULL DEFAULT (datetime('now')),
  metadata TEXT NOT NULL DEFAULT '{}'
);

CREATE TABLE `users` (
	`id` text PRIMARY KEY NOT NULL,
	`username` text NOT NULL,
	`password_hash` text NOT NULL,
	`display_name` text DEFAULT '' NOT NULL,
	`role` text DEFAULT 'admin' NOT NULL,
	`created_at` text DEFAULT '(datetime(''now''))' NOT NULL,
	`updated_at` text DEFAULT '(datetime(''now''))' NOT NULL,
	`last_login_at` text,
	`email` text
);

CREATE TABLE `webhook_deliveries` (
	`id` text PRIMARY KEY NOT NULL,
	`subscription_id` text NOT NULL,
	`event_type` text NOT NULL,
	`payload` text NOT NULL,
	`status` text DEFAULT 'pending' NOT NULL,
	`status_code` integer,
	`response_body` text,
	`attempts` integer DEFAULT 0 NOT NULL,
	`created_at` text DEFAULT '(datetime(''now''))' NOT NULL,
	`last_attempt_at` text,
	`next_retry_at` text, `lease_owner` TEXT, `lease_fence` TEXT, `lease_expires_at` TEXT,
	FOREIGN KEY (`subscription_id`) REFERENCES `webhook_subscriptions`(`id`) ON UPDATE no action ON DELETE cascade
);

CREATE TABLE `webhook_subscriptions` (
	`id` text PRIMARY KEY NOT NULL,
	`habitat_id` text,
	`name` text NOT NULL,
	`url` text NOT NULL,
	`secret` text,
	`events` text NOT NULL,
	`headers` text NOT NULL,
	`format` text DEFAULT 'standard' NOT NULL,
	`enabled` integer DEFAULT 1 NOT NULL,
	`created_at` text DEFAULT '(datetime(''now''))' NOT NULL,
	`updated_at` text DEFAULT '(datetime(''now''))' NOT NULL,
	FOREIGN KEY (`habitat_id`) REFERENCES `habitats`(`id`) ON UPDATE no action ON DELETE cascade
);

CREATE TABLE wiki_coverage_markers (
  `id` text PRIMARY KEY NOT NULL,
  `habitat_id` text NOT NULL,
  `coverage_from` text NOT NULL,
  `coverage_to` text NOT NULL,
  `marker_type` text NOT NULL,
  `page_id` text,
  `reason` text,
  `created_by` text NOT NULL,
  `created_at` text DEFAULT (datetime('now')) NOT NULL,
  FOREIGN KEY (`habitat_id`) REFERENCES `habitats`(`id`) ON DELETE cascade,
  FOREIGN KEY (`page_id`) REFERENCES `wiki_pages`(`id`) ON DELETE cascade
);

CREATE TABLE wiki_page_links (
  `id` text PRIMARY KEY NOT NULL,
  `page_id` text NOT NULL,
  `target_type` text NOT NULL,
  `target_id` text NOT NULL,
  `link_note` text,
  `created_by` text NOT NULL,
  `created_at` text DEFAULT (datetime('now')) NOT NULL,
  FOREIGN KEY (`page_id`) REFERENCES `wiki_pages`(`id`) ON DELETE cascade,
  UNIQUE(`page_id`, `target_type`, `target_id`)
);

CREATE TABLE wiki_page_versions (
  `id` text PRIMARY KEY NOT NULL,
  `page_id` text NOT NULL,
  `version_number` integer NOT NULL,
  `title` text NOT NULL,
  `content` text NOT NULL,
  `edit_summary` text,
  `edited_by` text NOT NULL,
  `created_at` text DEFAULT (datetime('now')) NOT NULL,
  FOREIGN KEY (`page_id`) REFERENCES `wiki_pages`(`id`) ON DELETE cascade
);

CREATE TABLE wiki_pages (
  `id` text PRIMARY KEY NOT NULL,
  `habitat_id` text NOT NULL,
  `parent_id` text,
  `slug` text NOT NULL,
  `title` text NOT NULL,
  `content` text DEFAULT '' NOT NULL,
  `status` text DEFAULT 'draft' NOT NULL,
  `tags` text NOT NULL,
  `current_version_number` integer DEFAULT 1 NOT NULL,
  `created_by` text NOT NULL,
  `last_updated_by` text NOT NULL,
  `last_updated_at` text DEFAULT (datetime('now')) NOT NULL,
  `created_at` text DEFAULT (datetime('now')) NOT NULL,
  `updated_at` text DEFAULT (datetime('now')) NOT NULL,
  FOREIGN KEY (`habitat_id`) REFERENCES `habitats`(`id`) ON DELETE cascade,
  FOREIGN KEY (`parent_id`) REFERENCES `wiki_pages`(`id`) ON DELETE no action
);

CREATE TABLE `workflows` (
	`id` text PRIMARY KEY NOT NULL,
	`mission_id` text NOT NULL,
	`habitat_id` text NOT NULL,
	`resolved_variables` text NOT NULL,
	`failure_handler` text,
	`status` text DEFAULT 'active' NOT NULL,
	`created_by` text NOT NULL,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	`detached_at` text,
	`detached_by` text,
	`version` integer DEFAULT 1 NOT NULL, `join_specs` text,
	FOREIGN KEY (`mission_id`) REFERENCES `missions`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`habitat_id`) REFERENCES `habitats`(`id`) ON UPDATE no action ON DELETE cascade
);

